impl Solution{pub fn is_match(s:String,p:String)->bool{let(s,p)=(s.as_bytes(),p.as_bytes());let(m,n)=(s.len(),p.len());let mut d=vec![vec![false;n+1];m+1];d[0][0]=true;for j in 2..=n{if p[j-1]==b'*'{d[0][j]=d[0][j-2];}}for i in 1..=m{for j in 1..=n{if p[j-1]==b'.'||p[j-1]==s[i-1]{d[i][j]=d[i-1][j-1];}else if p[j-1]==b'*'{d[i][j]=d[i][j-2];if p[j-2]==b'.'||p[j-2]==s[i-1]{d[i][j]|=d[i-1][j];}}}}d[m][n]}}
